components.element:
{(({ setValue }, value, [state, setState]) => {
  useEffect(() => {
    props.source &&
      (value
        ? value.includes(props.source) ||
          setValue('parse', [...value, props.source])
        : setValue('parse', [props.source]))
  }, [setValue, value])
  return createElement(props.component, {
    ...props,
    source: props.source,
    parse: (value) => (() => props.parse(value))(setState(value)),
    format: () => state
  })
})(useFormContext(), useWatch({ name: 'parse' }), useState(''))}
